-- ==============================================================================
-- 🚀 SUPABASE POSTGRESQL MIGRATION: MCQ QUESTION BANK & DETERMINISTIC TAXONOMY
-- ==============================================================================
-- Generated for Supabase Project: https://jjgdatjthyeesmgunnlp.supabase.co
-- Features: Deterministic UIDs [SUB]-[DOM]-[TOP]-[SUBT]-[MIC]-[DIFF]-[SEQ],
--           Range Search (100 to 200), Category & Format Indexing, Full-Text GIN Index
-- ==============================================================================

-- 1. Create Dedicated edu_question_bank Table
CREATE TABLE IF NOT EXISTS public.edu_question_bank (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    question_uid VARCHAR(64) UNIQUE NOT NULL,
    sequence_number INT NOT NULL,
    subject VARCHAR(64) NOT NULL,
    subject_code VARCHAR(16) NOT NULL,
    domain VARCHAR(64) NOT NULL,
    domain_code VARCHAR(16) NOT NULL,
    topic VARCHAR(128) NOT NULL,
    topic_code VARCHAR(8) NOT NULL,
    subtopic VARCHAR(128) NOT NULL,
    subtopic_code VARCHAR(8) NOT NULL,
    microtopic VARCHAR(128) NOT NULL,
    microtopic_code VARCHAR(8) NOT NULL,
    difficulty VARCHAR(16) NOT NULL CHECK (difficulty IN ('Easy', 'Medium', 'Hard')),
    exam_category VARCHAR(32) NOT NULL DEFAULT 'ALL',
    question_format VARCHAR(32) NOT NULL DEFAULT 'single_choice',
    question_text TEXT NOT NULL,
    question_text_ta TEXT,
    options JSONB NOT NULL,
    options_ta JSONB,
    correct_option VARCHAR(2) NOT NULL CHECK (correct_option IN ('A', 'B', 'C', 'D')),
    explanation TEXT NOT NULL,
    explanation_ta TEXT,
    formula_or_law TEXT,
    is_active BOOLEAN DEFAULT TRUE,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 2. Performance Indexes for Ultra-Fast Range & Category Filtering
CREATE INDEX IF NOT EXISTS idx_qbank_sequence_number ON public.edu_question_bank(sequence_number);
CREATE INDEX IF NOT EXISTS idx_qbank_subject_code ON public.edu_question_bank(subject_code);
CREATE INDEX IF NOT EXISTS idx_qbank_exam_category ON public.edu_question_bank(exam_category);
CREATE INDEX IF NOT EXISTS idx_qbank_question_format ON public.edu_question_bank(question_format);
CREATE INDEX IF NOT EXISTS idx_qbank_difficulty ON public.edu_question_bank(difficulty);
CREATE INDEX IF NOT EXISTS idx_qbank_uid ON public.edu_question_bank(question_uid);

-- 3. Full-Text Search GIN Index for Word Search
CREATE INDEX IF NOT EXISTS idx_qbank_fts ON public.edu_question_bank 
USING gin(to_tsvector('english', question_text || ' ' || explanation || ' ' || topic || ' ' || subtopic));

-- 4. Enable Row Level Security (RLS) & Allow Read for Anon / Authenticated Users
ALTER TABLE public.edu_question_bank ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Allow public read access on edu_question_bank"
ON public.edu_question_bank FOR SELECT
TO anon, authenticated
USING (true);

