    '[கேள்வி எண் #0113] முதல் வகை வினைக்கு அரைவாழ்வு காலம் தொடக்கச் செறிவைச் சார்ந்திருக்காது: t_1/2 = 0.693 / k.',
    't_{1/2} = \frac{\ln 2}{k} = \frac{0.693}{k}'
),
