    '[கேள்வி எண் #0116] AVL மரத்தில் இடது மற்றும் வலது துணை மரங்களின் உயர வேறுபாடு எப்போதும் -1, 0, அல்லது +1 ஆக மட்டுமே இருக்க வேண்டும்.',
    '\text{BF}(v) = h(\text{left}(v)) - h(\text{right}(v)) \in \{-1, 0, +1\}'
),
