    '[#0190] P என்ற அசல் தொகைக்கு R% ஆண்டு தனிவட்டி வீதத்தில் N ஆண்டுகளில் கிடைக்கும் தனிவட்டி SI எனில், மொத்தத் தொகை A கணக்கிடும் சூத்திரம்:',
    '{"A":"A = P [1 + (R * N) / 100]","B":"A = P [1 + R / 100]^N","C":"A = (P * R * N) / 100","D":"A = P / [1 + (R * N) / 100]"}'::jsonb,
    NULL,
