    '[Question #0190] Total Amount A = Principal P + Simple Interest SI = P + (P * R * N) / 100 = P [1 + (R * N) / 100].',
    '[கேள்வி எண் #0190] மொத்தத் தொகை A = அசல் + தனிவட்டி = P [1 + (R * N) / 100].',
    'A = P \left(1 + \frac{R \cdot N}{100}\right)'
),
