    '{"A":"t_1/2 = 0.693 / k (independent of initial concentration)","B":"t_1/2 = [A]_0 / (2k)","C":"t_1/2 = 1 / (k [A]_0)","D":"t_1/2 = 2.303 / (k [A]_0)"}'::jsonb,
