    '[#0240] If the simple interest on a principal sum P at R% per annum for N years is SI = (P * R * N) / 100, what will be the total accumulated amount A after N years?',
    '[#0240] P என்ற அசல் தொகைக்கு R% ஆண்டு தனிவட்டி வீதத்தில் N ஆண்டுகளில் கிடைக்கும் தனிவட்டி SI எனில், மொத்தத் தொகை A கணக்கிடும் சூத்திரம்:',
    '{"A":"A = P [1 + (R * N) / 100]","B":"A = P [1 + R / 100]^N","C":"A = (P * R * N) / 100","D":"A = P / [1 + (R * N) / 100]"}'::jsonb,
    NULL,
    'A',
    '[Question #0240] Total Amount A = Principal P + Simple Interest SI = P + (P * R * N) / 100 = P [1 + (R * N) / 100].',
    '[கேள்வி எண் #0240] மொத்தத் தொகை A = அசல் + தனிவட்டி = P [1 + (R * N) / 100].',
    'A = P \left(1 + \frac{R \cdot N}{100}\right)'
),
