    '[#0250] If the simple interest on a principal sum P at R% per annum for N years is SI = (P * R * N) / 100, what will be the total accumulated amount A after N years?',
    '[#0250] P என்ற அசல் தொகைக்கு R% ஆண்டு தனிவட்டி வீதத்தில் N ஆண்டுகளில் கிடைக்கும் தனிவட்டி SI எனில், மொத்தத் தொகை A கணக்கிடும் சூத்திரம்:',
    '{"A":"A = P [1 + (R * N) / 100]","B":"A = P [1 + R / 100]^N","C":"A = (P * R * N) / 100","D":"A = P / [1 + (R * N) / 100]"}'::jsonb,
    NULL,
    'A',
    '[Question #0250] Total Amount A = Principal P + Simple Interest SI = P + (P * R * N) / 100 = P [1 + (R * N) / 100].',
    '[கேள்வி எண் #0250] மொத்தத் தொகை A = அசல் + தனிவட்டி = P [1 + (R * N) / 100].',
    'A = P \left(1 + \frac{R \cdot N}{100}\right)'
)
ON CONFLICT (question_uid) DO UPDATE SET
    question_text = EXCLUDED.question_text,
    question_text_ta = EXCLUDED.question_text_ta,
    options = EXCLUDED.options,
    options_ta = EXCLUDED.options_ta,
    correct_option = EXCLUDED.correct_option,
    explanation = EXCLUDED.explanation,
    explanation_ta = EXCLUDED.explanation_ta,
    formula_or_law = EXCLUDED.formula_or_law,
    updated_at = NOW();

-- ==============================================================================
-- 3. COMPATIBILITY INSERT: unified_master_data (item_type = 'MCQ_QBANK')
-- ==============================================================================
INSERT INTO public.unified_master_data (item_type, category, language, description, metadata)
SELECT 
    'MCQ_QBANK' as item_type,
    subject_code as category,
    'en' as language,
    question_text as description,
    jsonb_build_object(
        'question_uid', question_uid,
        'sequence_number', sequence_number,
        'taxonomy', jsonb_build_object(
            'subject', subject,
            'subject_code', subject_code,
            'domain', domain,
            'domain_code', domain_code,
            'topic', topic,
            'topic_code', topic_code,
            'subtopic', subtopic,
            'subtopic_code', subtopic_code,
            'microtopic', microtopic,
            'microtopic_code', microtopic_code,
            'difficulty', difficulty,
            'exam_category', exam_category,
            'question_format', question_format
        ),
        'exam_category', exam_category,
        'question_format', question_format,
        'question_text', question_text,
        'question_text_ta', question_text_ta,
        'options', options,
        'options_ta', options_ta,
        'correct_option', correct_option,
        'explanation', explanation,
        'explanation_ta', explanation_ta,
        'formula_or_law', formula_or_law
    ) as metadata
FROM public.edu_question_bank
ON CONFLICT DO NOTHING;
